      background: linear-gradient(135deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.02));
    }

    .preview-art::before {
      width: 10rem;
      height: 10rem;
      left: 12%;
      bottom: -1rem;
    }

    .preview-art::after {
      width: 7rem;
      height: 7rem;
      right: 15%;
      top: 18%;
    }

    main {
      padding-bottom: 4rem;
    }

    section {
      margin-top: 1.25rem;
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-head h2 {
      margin: 0;
      font-size: clamp(1.45rem, 2.5vw, 2.1rem);
      letter-spacing: -0.03em;
    }

    .section-head p {
      margin: 0;
      color: var(--muted);
      max-width: 58ch;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
    }

    .pill {
      min-height: 2.7rem;
      border-radius: 999px;
      padding: 0.45rem 0.9rem;
      border: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.02);
      color: var(--muted-strong);
    }

    .pill[aria-pressed="true"] {
      background: rgba(141, 240, 200, 0.12);
      border-color: rgba(141, 240, 200, 0.28);
      color: var(--text);
    }

    .grid-products {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 1rem;
    }

    .product-card {
      grid-column: span 4;
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
      min-width: 0;
    }

    .product-visual {
      border-radius: 20px;
      aspect-ratio: 4 / 3;
      border: 1px solid rgba(255, 255, 255, 0.08);
      overflow: hidden;
      background: linear-gradient(135deg, #151b26, #0f1218);
    }

    .product-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .product-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      align-items: start;
    }

    .product-meta h3 {
      margin: 0;
      font-size: 1.05rem;
    }

    .tag {
      display: inline-flex;
      padding: 0.22rem 0.55rem;
      border-radius: 999px;
      background: rgba(143, 180, 255, 0.12);
      color: #cfe0ff;
      font-size: 0.8rem;
      font-weight: 650;
      white-space: nowrap;
    }

    .product-card p {
      margin: 0;
      color: var(--muted);
      min-width: 0;
      overflow-wrap: anywhere;
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .price {
      font-size: 1.1rem;
      font-weight: 700;
    }

    .was {
      color: var(--muted);
      text-decoration: line-through;
      margin-left: 0.35rem;
      font-size: 0.93rem;
    }

    .product-card .btn {
      width: 100%;
    }

    .deals-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
    }

    .deal-feature {
      padding: 1.25rem;
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
      align-items: center;
    }

    .deal-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      background: rgba(255, 184, 107, 0.12);
      color: #ffd19f;
      border: 1px solid rgba(255, 184, 107, 0.2);
      width: fit-content;
    }

    .deal-feature h3 {
      margin: 0.75rem 0 0.5rem;
      font-size: clamp(1.45rem, 2vw, 2rem);
    }

    .deal-feature p {
      margin: 0;
      color: var(--muted);
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .time-box {
      padding: 0.85rem;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.08);
      text-align: center;
    }

    .time-box strong {
      display: block;
      font-size: 1.45rem;
      line-height: 1;
    }

    .time-box span {
      color: var(--muted);
      font-size: 0.84rem;
    }

    .deal-side {
      display: grid;
      gap: 1rem;
    }

    .deal-mini {
      padding: 1rem;
    }

    .deal-mini h3 {
      margin: 0 0 0.3rem;
      font-size: 1.03rem;
    }

    .deal-mini p {
      margin: 0;
      color: var(--muted);
    }

    .deal-mini .row {
      margin-top: 0.9rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 1rem;
    }

    .story-card {
      grid-column: span 4;
      padding: 1rem;
      display: grid;
      gap: 0.9rem;
      min-width: 0;
    }

    .story-thumb {
      aspect-ratio: 16 / 10;
      border-radius: 20px;
      background:
        linear-gradient(135deg, rgba(143, 180, 255, 0.3), rgba(141, 240, 200, 0.16)),
        linear-gradient(180deg, #191f2a, #10141b);
      border: 1px solid rgba(255, 255, 255, 0.08);
      position: relative;
      overflow: hidden;
    }

    .story-thumb::after {
      content: "";
      position: absolute;
      inset: auto 12% 10% auto;
      width: 42%;
      height: 42%;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255, 255, 255, 0.36), transparent 70%);
    }

    .story-card h3 {
      margin: 0;
      font-size: 1.1rem;
    }

    .story-card p {
      margin: 0;
      color: var(--muted);
    }

    .story-link {
      color: var(--accent);
      font-weight: 650;
      width: fit-content;
    }

    .newsletter {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 0.75rem;
      align-items: end;
      padding: 1.25rem;
    }

    .newsletter h2 {
      margin: 0 0 0.35rem;
    }

    .newsletter p {
      margin: 0;
      color: var(--muted);
    }

    label {
      display: block;
      font-weight: 600;
      margin-bottom: 0.45rem;
    }

    .field {
      display: grid;
      gap: 0.35rem;
      min-width: 0;
    }

    input[type="email"] {
      width: 100%;
      min-height: 3rem;
      padding: 0.75rem 0.9rem;
      border-radius: 14px;
      border: 1px solid var(--border-strong);
      color: var(--text);
      background: rgba(255, 255, 255, 0.03);
    }

    input[type="email"]::placeholder {
      color: #7f8a9c;
    }

    .helper {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .status {
      min-height: 1.5rem;
      color: var(--accent);
      font-size: 0.94rem;
      margin-top: 0.75rem;
    }

    footer {
      padding: 2rem 0 2.6rem;
      color: var(--muted);
    }

    .footer-grid {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
    }

    @media (max-width: 980px) {
      .hero-grid,
      .deals-grid,
      .deal-feature,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .product-card,
      .story-card {
        grid-column: span 6;
      }
    }

    @media (max-width: 720px) {
      .topbar {
        flex-direction: column;
        align-items: start;
      }

      nav ul {
        gap: 0.25rem;
      }

      .product-card,
      .story-card {
        grid-column: span 12;
      }

      .countdown {
        grid-template-columns: repeat(2, 1fr);
      }

      .hero {
        padding-top: 1.4rem;
      }
    }

    @media (forced-colors: active) {
      * {
        forced-color-adjust: auto;
      }

      body {
        background: Canvas;
        color: CanvasText;
      }

      .panel,
      .product-visual,
      .story-thumb,
      .stat-card,
      .promo-card,
      .time-box,
      input[type="email"] {
        border-color: ButtonBorder;
      }

      .btn-primary,
      .deal-badge,
      .pill[aria-pressed="true"],
      .tag,
      .eyebrow {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header>
    <div class="site-shell topbar">
      <a class="brand" href="#" aria-label="Northstar Supply home">
