          <div class="pills" role="toolbar" aria-label="Featured product filters">
            <button class="pill" type="button" data-filter="all" aria-pressed="true">All</button>
            <button class="pill" type="button" data-filter="apparel" aria-pressed="false">Apparel</button>
            <button class="pill" type="button" data-filter="home" aria-pressed="false">Home</button>
            <button class="pill" type="button" data-filter="travel" aria-pressed="false">Travel</button>
          </div>
        </div>
        <div class="grid-products" id="product-grid" aria-live="polite"></div>
      </section>

      <section id="deals" aria-labelledby="deals-title">
        <div class="section-head">
          <div>
            <h2 id="deals-title">Deals that feel premium, not rushed</h2>
            <p>Limited-time offers with clear savings and a live countdown for the weekend event.</p>
          </div>
        </div>

        <div class="deals-grid">
          <article class="panel deal-feature">
            <div>
              <span class="deal-badge">48-hour doorbuster</span>
              <h3>Upgrade your carry kit with 30% off the Metro Weekender.</h3>
              <p>
                Reinforced canvas, water-resistant trim, and a padded sleeve make it ready for work trips and
                long weekends.
              </p>
              <div class="countdown" aria-label="Countdown to weekend event">
                <div class="time-box">
                  <strong data-countdown="days">00</strong>
                  <span>Days</span>
                </div>
                <div class="time-box">
                  <strong data-countdown="hours">00</strong>
                  <span>Hours</span>
                </div>
                <div class="time-box">
                  <strong data-countdown="minutes">00</strong>
                  <span>Minutes</span>
                </div>
                <div class="time-box">
                  <strong data-countdown="seconds">00</strong>
                  <span>Seconds</span>
                </div>
              </div>
            </div>

            <div class="product-visual" aria-hidden="true">
              <img
                alt=""
                src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 640 480'%3E%3Cdefs%3E%3ClinearGradient id='g1' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%231b2433'/%3E%3Cstop offset='1' stop-color='%230f1218'/%3E%3C/linearGradient%3E%3ClinearGradient id='g2' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%238df0c8'/%3E%3Cstop offset='1' stop-color='%238fb4ff'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='640' height='480' rx='34' fill='url(%23g1)'/%3E%3Ccircle cx='470' cy='125' r='92' fill='url(%23g2)' fill-opacity='.18'/%3E%3Crect x='180' y='110' width='240' height='250' rx='38' fill='url(%23g2)' fill-opacity='.28'/%3E%3Crect x='222' y='156' width='156' height='152' rx='22' fill='%230f1218'/%3E%3Crect x='208' y='84' width='200' height='48' rx='18' fill='%23141922'/%3E%3Crect x='256' y='64' width='104' height='28' rx='12' fill='%238df0c8' fill-opacity='.8'/%3E%3C/svg%3E"
              >
            </div>
          </article>

          <div class="deal-side">
            <article class="panel deal-mini">
              <h3>2 for $88 on organic tees</h3>
              <p>Everyday basics with a softer handfeel and a cleaner neckline.</p>
