  <footer>
    <div class="site-shell footer-grid">
      <span>Northstar Supply</span>
      <span>Dark retail concept built with plain HTML, CSS, and vanilla JavaScript.</span>
    </div>
  </footer>

  <script>
    const products = [
      {
        category: "apparel",
        tag: "Best seller",
        name: "Meridian Overshirt",
        price: "$118",
        was: "$148",
        description: "Soft brushed twill with hidden pockets and a structured drape.",
        alt: "Dark overshirt product render with layered fabric folds",
        hue: "#8fb4ff"
      },
      {
        category: "home",
        tag: "New",
        name: "Atelier Candle Set",
        price: "$42",
        was: "$56",
        description: "Three clean-burning scents with ceramic vessels made for shelf display.",
        alt: "Three candles arranged on a dark tabletop",
        hue: "#ffb86b"
      },
      {
        category: "travel",
        tag: "Top rated",
        name: "Metro Weekender",
        price: "$164",
        was: "$210",
        description: "A structured travel bag with a laptop sleeve, bottle pocket, and trolley pass-through.",
        alt: "Travel duffel bag with premium trim on a dark background",
        hue: "#8df0c8"
      },
      {
        category: "apparel",
        tag: "Essential",
        name: "Everyday Knit Tee",
        price: "$38",
        was: "$48",
        description: "Breathable cotton blend designed to keep its shape after repeated wear.",
        alt: "Minimal knit t-shirt laid flat under moody lighting",
        hue: "#9bc3ff"
      },
      {
        category: "home",
        tag: "Limited",
        name: "Soft Loft Throw",
        price: "$96",
        was: "$120",
        description: "Oversized, tactile, and warm enough for sofa layering or late-night reading.",
        alt: "Folded textured throw blanket with a soft drape",
        hue: "#ffd19f"
      },
      {
        category: "travel",
        tag: "Member pick",
        name: "Transit Tech Pouch",
        price: "$34",
        was: "$44",
        description: "Organize chargers, earbuds, and cables without bulky bulk.",
        alt: "Compact zip pouch for travel accessories on a dark surface",
        hue: "#95f2cd"
      }
    ];

    const productGrid = document.getElementById("product-grid");
    const filterButtons = document.querySelectorAll("[data-filter]");
    const status = document.getElementById("email-status");
    const form = document.getElementById("newsletter-form");
    const emailInput = document.getElementById("email");
    const countdownEls = {
      days: document.querySelector('[data-countdown="days"]'),
      hours: document.querySelector('[data-countdown="hours"]'),
      minutes: document.querySelector('[data-countdown="minutes"]'),
      seconds: document.querySelector('[data-countdown="seconds"]')
    };

    let activeFilter = "all";
    const eventEndsAt = new Date(Date.now() + (2 * 24 * 60 * 60 + 17 * 60 * 60 + 34 * 60 + 12) * 1000);

    const shadeSvg = (hue, name) => {
      const safeName = encodeURIComponent(name);
      return `data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 640 480'%3E%3Cdefs%3E%3ClinearGradient id='bg' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%23141922'/%3E%3Cstop offset='1' stop-color='%230b0d12'/%3E%3C/linearGradient%3E%3ClinearGradient id='accent' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='${encodeURIComponent(hue)}'/%3E%3Cstop offset='1' stop-color='%23ffffff' stop-opacity='.15'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='640' height='480' rx='34' fill='url(%23bg)'/%3E%3Ccircle cx='475' cy='130' r='104' fill='url(%23accent)' fill-opacity='.18'/%3E%3Crect x='168' y='118' width='304' height='244' rx='34' fill='url(%23accent)' fill-opacity='.28'/%3E%3Crect x='208' y='160' width='224' height='160' rx='22' fill='%2310141b'/%3E%3Ctext x='50%25' y='390' text-anchor='middle' font-family='Inter,Arial,sans-serif' font-size='28' fill='%23a3afc1'%3E${safeName}%3C/text%3E%3C/svg%3E`;
    };

    const renderProducts = () => {
      const visibleProducts = products.filter((product) => activeFilter === "all" || product.category === activeFilter);

      productGrid.innerHTML = visibleProducts.map((product) => `
        <article class="panel product-card">
          <div class="product-visual">
            <img src="${shadeSvg(product.hue, product.name)}" alt="${product.alt}">
          </div>
          <div class="product-meta">
            <h3>${product.name}</h3>
            <span class="tag">${product.tag}</span>
          </div>
          <p>${product.description}</p>
          <div class="price-row">
            <div>
              <span class="price">${product.price}</span>
              <span class="was">${product.was}</span>
            </div>
          </div>
          <button class="btn btn-secondary" type="button" data-add-to-cart="${product.name}">Quick add</button>
        </article>
      `).join("");
    };

    const setFilter = (filter) => {
      activeFilter = filter;
      filterButtons.forEach((button) => {
        const pressed = button.dataset.filter === filter;
        button.setAttribute("aria-pressed", String(pressed));
      });
      renderProducts();
    };

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => setFilter(button.dataset.filter));
    });

    productGrid.addEventListener("click", (event) => {
      const button = event.target.closest("[data-add-to-cart]");
      if (!button) return;

      status.textContent = `${button.dataset.addToCart} added to your saved picks.`;
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const value = emailInput.value.trim();

      if (!emailInput.checkValidity()) {
        emailInput.reportValidity();
        emailInput.setAttribute("aria-invalid", "true");
        emailInput.focus();
        status.textContent = "Enter a valid email address to join the newsletter.";
        return;
      }

      emailInput.removeAttribute("aria-invalid");
      status.textContent = `Thanks — updates will go to ${value}.`;
      form.reset();
    });

    emailInput.addEventListener("input", () => {
      if (emailInput.validity.valid) {
        emailInput.removeAttribute("aria-invalid");
      }
    });

