     a {
       color: inherit;
       text-decoration: none;
     }

     img {
       max-width: 100%;
       display: block;
     }

     button,
     input {
       font: inherit;
     }

     button {
       cursor: pointer;
     }

     :focus-visible {
       outline: 3px solid var(--accent);
       outline-offset: 3px;
     }

     .skip-link {
