     .btn-primary {
       background: linear-gradient(135deg, var(--accent), #bdf9e4);
       color: #07120f;
       box-shadow: 0 10px 25px rgba(141, 240, 200, 0.12);
     }

     .btn-secondary {
       border-color: var(--border-strong);
       color: var(--text);
       background: rgba(255, 255, 255, 0.02);
     }

     .btn:hover {
       transform: translateY(-1px);
     }

     .hero-aside {
       display: grid;
       gap: 1rem;
       padding: 1rem;
     }

     .stat-card,
     .promo-card {
       padding: 1.1rem;
       border-radius: var(--radius-md);
